import {seed} from './engine.js';import {sampleCode,skuFor} from './barcodes.js';const state=seed(),select=document.querySelector('#stock'),type=document.querySelector('#type'),params=new URLSearchParams(location.search);select.innerHTML=state.stocks.filter(s=>s.id!=='P3').map(s=>`<option value="${s.id}">${s.name} / ${s.lot}</option>`).join('');select.value=state.stocks.some(x=>x.id===params.get('stock'))?params.get('stock'):'P1';document.querySelector('#print').onclick=()=>window.print();select.onchange=render;type.onchange=render;function render(){const s=state.stocks.find(s=>s.id===select.value),count=s.id==='P4'?30:3,mode=type.value;document.querySelector('#notice').textContent=mode==='package'?'고유 포장마다 코드가 다릅니다. 같은 라벨은 두 번 등록하지 않습니다. 첫 번째 라벨부터 차례로 스캔하세요.':mode==='box'?`같은 포장코드로 포장당 ${s.pack} ${s.unit}를 셉니다. 라벨을 카메라 밖으로 뺐다가 다음 실물 라벨을 비춰 주세요.`:s.unit==='kg'?'원자재 상품코드는 중량을 담지 않습니다. 앱에서 실측 중량(kg)을 먼저 입력한 뒤 스캔하세요.':'상품코드는 1회 인식마다 1 EA입니다. 카메라 밖으로 뺐다가 다음 실물을 비춰 주세요.';document.querySelector('#labels').innerHTML=Array.from({length:mode==='package'?count:1},(_,i)=>{const code=mode==='package'?sampleCode(s.id,i+1):mode==='box'?'BOX-'+s.item:skuFor(s.item),image=mode==='package'?code:mode==='box'?'BOX-'+s.item:'SKU-'+s.item;return `<article class="label"><small>맑은물에 FIELD · 가상 라벨</small><h2>${s.name}</h2><p>LOT ${s.lot}</p><p>${s.warehouse} · ${s.expiry?'소비기한 '+s.expiry:'소비기한 해당 없음'}</p><p class="qty">${mode==='sku'?(s.unit==='kg'?'실측 중량 입력':'1 EA'):s.pack+' '+s.unit}</p><img src="labels/${image}.svg" alt="${code} 바코드"><strong>${code}</strong><footer>${mode==='package'?'Code 128 · 품목 / LOT / 포장수량 / 고유 포장 ID 연결':mode==='box'?'Code 128 · 포장수량은 데모 마스터에서 조회':'EAN-13 · 품목 식별용, 가상 데이터'}</footer></article>`;}).join('');}render();
